"use client";

import { useEffect, useMemo, useState } from "react";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

interface FacultyLoadResponse {
  success: boolean;
  data: {
    instructor_id: number | null;
    instructor_name: string | null;
    total_load: number;
    credit_hours: number;
    load_utilization: number;
    active_assignments: number;
    pending_assignments: number;
  };
}

interface ScheduleResponse {
  success: boolean;
  data: Array<{
    id: number;
    day_of_week?: string;
    time_start?: string;
    time_end?: string;
    course?: { course_code?: string; course_title?: string; units?: number };
    section?: { section_name?: string };
    room?: { room_number?: string };
  }>;
}

interface RequestResponse {
  success: boolean;
  data: Array<{
    id: number;
    status: string;
    preferred_day_of_week?: string;
    preferred_start_time?: string;
    preferred_end_time?: string;
    course?: { course_code?: string; course_title?: string; units?: number };
    section?: { section_name?: string };
  }>;
}

const fmtTime = (t?: string) => (t ? t.slice(0, 5) : "--:--");

export default function InstructorFacultyLoadPage() {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [summary, setSummary] = useState<FacultyLoadResponse["data"] | null>(null);
  const [confirmed, setConfirmed] = useState<ScheduleResponse["data"]>([]);
  const [pending, setPending] = useState<RequestResponse["data"]>([]);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        setLoading(true);
        setError(null);
        const [loadRes, schedRes, reqRes] = await Promise.all([
          api.get<FacultyLoadResponse>("/instructor/faculty-load"),
          api.get<ScheduleResponse>("/instructor/schedule"),
          api.get<RequestResponse>("/requests?status=Pending&per_page=50"),
        ]);
        if (!active) return;
        setSummary(loadRes.data);
        setConfirmed(schedRes.data ?? []);
        setPending((reqRes.data ?? []).filter((r) => r.status === "Pending"));
      } catch (e) {
        if (!active) return;
        setError(e instanceof Error ? e.message : "Failed to load faculty load.");
      } finally {
        if (active) setLoading(false);
      }
    })();
    return () => {
      active = false;
    };
  }, []);

  const maxUnits = 24;
  const totalUnits = summary?.total_load ?? 0;
  const pendingUnits = useMemo(
    () => pending.reduce((sum, p) => sum + Number(p.course?.units ?? 0), 0),
    [pending]
  );
  const remainingUnits = Math.max(maxUnits - totalUnits - pendingUnits, 0);

  return (
    <AppShell role="instructor" userName={summary?.instructor_name ?? "Instructor"} pageTitle="My Faculty Load">
      <div className="space-y-6">
        <div>
          <h1 className="text-xl font-semibold" style={{ color: "var(--color-text)" }}>Faculty Load Overview</h1>
          <p className="text-sm mt-0.5" style={{ color: "var(--color-text-secondary)" }}>
            {loading ? "Loading..." : "Current semester load summary"}
          </p>
        </div>

        {error && (
          <div className="rounded-lg border px-4 py-3 text-sm" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>
            {error}
          </div>
        )}

        <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
          <SummaryCard label="Units Loaded" value={totalUnits.toFixed(1)} sub={`of ${maxUnits} max`} />
          <SummaryCard label="Pending Units" value={pendingUnits.toFixed(1)} sub="awaiting approval" />
          <SummaryCard label="Confirmed Classes" value={String(confirmed.length)} sub="active schedules" />
          <SummaryCard label="Units Available" value={remainingUnits.toFixed(1)} sub="remaining capacity" />
        </div>

        <div className="card overflow-hidden">
          <div className="px-6 py-4 border-b" style={{ borderColor: "var(--color-border)" }}>
            <h2 className="text-sm font-semibold" style={{ color: "var(--color-text)" }}>Confirmed Sections</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead><tr><th>Course</th><th>Section</th><th>Units</th><th>Day</th><th>Time</th><th>Room</th></tr></thead>
              <tbody>
                {confirmed.map((c) => (
                  <tr key={c.id}>
                    <td className="text-xs">{c.course?.course_code ?? "N/A"}</td>
                    <td className="text-xs">{c.section?.section_name ?? "N/A"}</td>
                    <td className="text-xs">{Number(c.course?.units ?? 0).toFixed(1)}</td>
                    <td className="text-xs">{c.day_of_week ?? "N/A"}</td>
                    <td className="text-xs">{fmtTime(c.time_start)} - {fmtTime(c.time_end)}</td>
                    <td className="text-xs">{c.room?.room_number ?? "TBA"}</td>
                  </tr>
                ))}
                {!loading && confirmed.length === 0 && <tr><td colSpan={6} className="text-center text-xs">No confirmed sections.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>

        <div className="card overflow-hidden">
          <div className="px-6 py-4 border-b" style={{ borderColor: "var(--color-border)" }}>
            <h2 className="text-sm font-semibold" style={{ color: "var(--color-text)" }}>Pending Sections</h2>
          </div>
          <div className="overflow-x-auto">
            <table className="table-base">
              <thead><tr><th>Course</th><th>Section</th><th>Units</th><th>Day</th><th>Time</th><th>Status</th></tr></thead>
              <tbody>
                {pending.map((p) => (
                  <tr key={p.id}>
                    <td className="text-xs">{p.course?.course_code ?? `Request #${p.id}`}</td>
                    <td className="text-xs">{p.section?.section_name ?? "N/A"}</td>
                    <td className="text-xs">{Number(p.course?.units ?? 0).toFixed(1)}</td>
                    <td className="text-xs">{p.preferred_day_of_week ?? "N/A"}</td>
                    <td className="text-xs">{fmtTime(p.preferred_start_time)} - {fmtTime(p.preferred_end_time)}</td>
                    <td className="text-xs">Pending</td>
                  </tr>
                ))}
                {!loading && pending.length === 0 && <tr><td colSpan={6} className="text-center text-xs">No pending sections.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </AppShell>
  );
}

function SummaryCard({ label, value, sub }: { label: string; value: string; sub: string }) {
  return (
    <div className="card card-body">
      <p className="text-xs mb-1" style={{ color: "var(--color-text-muted)" }}>{label}</p>
      <p className="text-2xl font-bold leading-none" style={{ color: "var(--color-text)" }}>{value}</p>
      <p className="text-xs mt-1" style={{ color: "var(--color-text-muted)" }}>{sub}</p>
    </div>
  );
}
